22: const SAVE='hollowmere_v1';
23: const ancestry={Human:'Versatile · +1 to any two abilities',Elf:'Keen senses · +2 DEX, +1 INT',Dwarf:'Stonewise · +2 CON, +1 WIS',Halfling:'Fortunate · +2 CHA, +1 DEX',Orc:'Iron-blooded · +2 STR, +1 CON',Tiefling:'Ember-touched · +2 CHA, +1 INT'};
24: const skills=['Athletics','Insight','Persuasion','Stealth','Survival','Arcana','Nature','Craft'];
25: const baseStats={STR:10,DEX:10,CON:10,INT:10,WIS:10,CHA:10};
26: const scenes=[
27:  {name:'Brackenmere',region:'THE GREENMARCH · BORDERLANDS',tag:'A village at the edge of old magic',intro:'Rain sighs over the slate roofs of Brackenmere. The village bell tolls once, though no hand pulls its rope. At the crossroads, three strangers watch you arrive.',choices:[['Speak with the ferrymaster','A worried ferryman has pinned a notice beside the river road.','☷','social'],['Follow the blue lights','Will-o’-wisps drift beyond the old standing stones.','✧','explore'],['Offer help at the shrine','A novice tends a shrine whose candles burn green.','☼','faith'],['Ask the villagers what they need','There is always work for a willing pair of hands.','⌂','craft']]},
28:  {name:'The Reed & Rook',region:'BRACKENMERE · COMMON ROOM',tag:'Where rumors find their voice',intro:'The common room smells of peat smoke and spiced cider. A mapmaker argues with the innkeeper; by the fire, a cloaked patron studies everyone but the door.',choices:[['Trade stories with the mapmaker','A well-told tale might earn more than a coin.','♧','social'],['Ask the innkeeper about work','She knows who is hiring—and who is lying.','☷','social'],['Study the stranger by the hearth','Their silver-ringed hand bears an unfamiliar sigil.','◉','explore'],['Help mend a broken chair','The innkeeper has tools beneath the counter.','⚒','craft']]},
29:  {name:'The Old Causeway',region:'GREENMARCH · NORTH ROAD',tag:'A road swallowed by the wild',intro:'Moss has swallowed the old stones, but fresh bootprints lead into the mist. A toppled milestone bears a name carefully scratched away.',choices:[['Track the fresh bootprints','The trail bends toward a copse of black alder.','⌖','explore'],['Examine the milestone','Something was carved here long ago.','⌕','lore'],['Clear the fallen stones','The road could be made safe for travelers.','⚒','craft'],['Leave a token for the road-god','The old ways deserve a little courtesy.','☼','faith']]},
30:  {name:'The Lantern Shrine',region:'BRACKENMERE · SACRED GROUND',tag:'A small light against a long night',intro:'Three candles burn beneath an arch of woven hazel. Their flames lean toward you, though there is no wind. The novice looks up, hopeful and afraid.',choices:[['Listen to the novice’s confession','She says the shrine has begun answering prayers.','♡','social'],['Tend the green flame','A gentle hand may reveal what force cannot.','☼','faith'],['Search the shrine’s old records','The names here go back hundreds of winters.','⌕','lore'],['Bring an offering from the wild','The spirits remember generosity.','✿','explore']]},
31:  {name:'The Lanternwood',region:'THE GREENMARCH · DEEPWOOD',tag:'Where the trees remember',intro:'The boughs close overhead, turning daylight to jade. A silver thread is tied around a birch trunk; somewhere nearby, a fox laughs like a child.',choices:[['Follow the silver thread','Each knot marks a turn deeper into the wood.','⌖','explore'],['Call out to the laughing fox','Something is listening from the bracken.','♧','social'],['Gather rare moonmoss','The apothecary would pay well for this.','✿','craft'],['Trace the runes on the birch','The marks shimmer faintly at your touch.','✧','lore']]}
32: ];
33: const gods=[['Aurel, the Hearth-Keeper','God of home, craft, and second chances'],['Nym, the Unmoored Star','Goddess of roads, chance, and the lost'],['Veyra of the Green Veil','Goddess of wild things and old bargains'],['Keth, the Last Witness','God of memory, truth, and endings']];
34: const items=[{id:'fieldkit',name:'Wayfarer’s field kit',icon:'⚒',desc:'A compact kit of useful tools.',type:'tool',value:8},{id:'amber',name:'Amberglass charm',icon:'✧',desc:'A warm, honey-colored shard. It hums near old magic.',type:'charm',value:14},{id:'bread',name:'Honey-oat bannock',icon:'◒',desc:'A good day’s food, wrapped in linen.',type:'food',value:2}];
35: const initial=()=>({created:false,name:'',ancestry:'Human',background:'Wanderer',skills:['Insight','Survival'],stats:{...baseStats},level:1,xp:0,gold:12,day:1,location:0,tab:'chronicle',quests:[{id:'bell',name:'The bell with no hand',desc:'Discover why Brackenmere’s bell tolls alone.',progress:0,total:3,done:false,reward:35}],inventory:[{...items[0],qty:1,equipped:false},{...items[1],qty:1,equipped:false},{...items[2],qty:2,equipped:false}],deeds:{},vocation:null,subclass:null,relations:{Mara:0,Rowan:0},joined:[],log:[],events:0,turn:0,offering:'',choiceCount:0,rollText:''});
36: let s;try{s=JSON.parse(localStorage.getItem(SAVE))||initial()}catch{s=initial()}
37: const el=(q,r=document)=>r.querySelector(q),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
38: function save(){try{localStorage.setItem(SAVE,JSON.stringify(s))}catch{};}
39: function mod(v){return Math.floor((v-10)/2)}function modText(n){return n>=0?'+'+n:String(n)}
40: function xpNeed(l=s.level){return l*100}
41: function skillBonus(skill){let stat={Athletics:'STR',Stealth:'DEX',Craft:'INT',Arcana:'INT',Nature:'WIS',Survival:'WIS',Insight:'WIS',Persuasion:'CHA'}[skill]||'WIS';return mod(s.stats[stat]||10)+(s.skills.includes(skill)?2:0)}
42: function pushLog(kind,text){s.log.unshift({kind,text,day:s.day});if(s.log.length>30)s.log.length=30}
43: function toast(msg){const t=el('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
44: function earned(){let scores=Object.entries(s.deeds).sort((a,b)=>b[1]-a[1]);if(!s.vocation&&s.level>=2&&scores[0]&&scores[0][1]>=3){let map={combat:'Warden',magic:'Arcanist',social:'Envoy',explore:'Wayfarer',craft:'Artificer',faith:'Luminary',lore:'Sage'};s.vocation=map[scores[0][0]]||'Wayfarer';pushLog('milestone',`Your deeds have revealed a calling: ${s.vocation}. You are no longer unclassed.`);toast(`Calling unlocked: ${s.vocation}`)}if(s.level>=3&&s.vocation&&!s.subclass){showSubclass()}}
45: function gainXP(n){s.xp+=n;let leveled=false;while(s.xp>=xpNeed()){s.xp-=xpNeed();s.level++;leveled=true;s.gold+=5;for(const k of Object.keys(s.stats))s.stats[k]=Math.min(20,s.stats[k]+(k==='CON'?1:0));pushLog('milestone',`You reached level ${s.level}. Your resolve deepens. (+5 silver marks)`)}if(leveled){toast(`Level up! You are now level ${s.level}.`);earned()}}
46: function render(){save();if(!s.created){renderCreator();return}updateShell();if(s.tab==='chronicle')renderChronicle();else if(s.tab==='character')renderCharacter();else if(s.tab==='quests')renderQuests();else if(s.tab==='inventory')renderInventory();else renderWorld();renderRight()}
47: function updateShell(){el('#sideName').textContent=s.name;el('#sideOrigin').textContent=`${s.ancestry} · ${s.background}`;el('#sideLevel').textContent=`Level ${s.level} · ${s.vocation||'Unclassed'}`;el('#sideXp').textContent=`${s.xp} / ${xpNeed()} XP`;el('#sideXpBar').style.width=`${Math.min(100,s.xp/xpNeed()*100)}%`;el('#levelTiny').textContent=`Level ${s.level+1}`;el('#headerDay').textContent=`✧ ${dayName(s.day)}`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===s.tab));el('#questBadge').textContent=s.quests.filter(q=>!q.done).length||'✓';}
48: function dayName(d){let names=['First day of Thaw','Second day of Thaw','Third day of Thaw','Fourth day of Thaw','Fifth day of Thaw'];return names[(d-1)%5]+(d>5?` · Day ${d}`:'')}
49: function renderCreator(){el('#rightbar').innerHTML='';el('#mainContent').innerHTML='<div style="height:45vh;min-height:300px;display:grid;place-items:center;text-align:center"><div><div class="sigil" style="margin:auto;width:58px;height:58px;font-size:28px">✦</div><div class="eyebrow" style="margin-top:20px">A world waiting to be changed</div><h1 style="font:600 34px var(--serif);margin:8px 0">Every legend begins<br>with a choice.</h1><p style="color:var(--muted);font:14px var(--serif);max-width:400px;line-height:1.6">There are no destinies here—only the life you choose to lead.</p><button class="primary" onclick="openCreator()" style="margin-top:14px">Begin your chronicle →</button></div></div>';}
50: window.openCreator=()=>{el('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-kicker">The first page</div><h1>Who will you become?</h1><p class="modal-intro">Make a person, not a build. Your choices shape your gifts; your actions will reveal a calling in time.</p><label class="form-label">Name</label><input id="charName" type="text" maxlength="24" placeholder="What shall the world call you?" value="${esc(s.name||'')}"/><label class="form-label">Ancestry</label><div class="options" id="ancestryOptions">${Object.entries(ancestry).map(([k,v])=>`<button class="option ${s.ancestry===k?'selected':''}" data-ancestry="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">A life before the road</label><div class="options" id="backgroundOptions">${[['Wanderer','You learned by going.'],['Apprentice','You learned by making.'],['Acolyte','You learned by listening.'],['Courtier','You learned by reading a room.'],['Outcast','You learned to endure.']].map(([k,v])=>`<button class="option ${s.background===k?'selected':''}" data-bg="${k}">${k}<small>${v}</small></button>`).join('')}</div><label class="form-label">Choose two practiced skills</label><div class="options" id="skillOptions">${skills.map(x=>`<button class="option ${s.skills.includes(x)?'selected':''}" data-skill="${x}">${x}</button>`).join('')}</div><div class="modal-actions"><span>All paths begin at level 1. No class is chosen.</span><button class="primary" id="createChar">Enter the Greenmarch →</button></div></div></div>`;
51:  el('#ancestryOptions').onclick=e=>{let b=e.target.closest('[data-ancestry]');if(!b)return;s.ancestry=b.dataset.ancestry;document.querySelectorAll('[data-ancestry]').forEach(x=>x.classList.toggle('selected',x===b))};el('#backgroundOptions').onclick=e=>{let b=e.target.closest('[data-bg]');if(!b)return;s.background=b.dataset.bg;document.querySelectorAll('[data-bg]').forEach(x=>x.classList.toggle('selected',x===b))};el('#skillOptions').onclick=e=>{let b=e.target.closest('[data-skill]');if(!b)return;let a=s.skills.slice();if(a.includes(b.dataset.skill))a=a.filter(x=>x!==b.dataset.skill);else if(a.length<2)a.push(b.dataset.skill);else toast('Choose exactly two practiced skills.');s.skills=a;document.querySelectorAll('[data-skill]').forEach(x=>x.classList.toggle('selected',a.includes(x.dataset.skill)))};el('#createChar').onclick=()=>{let name=el('#charName').value.trim();if(!name){toast('Give your wayfarer a name first.');el('#charName').focus();return}if(s.skills.length!==2){toast('Choose two practiced skills.');return}s.name=name;s.created=true;s.location=0;s.stats={...baseStats};let bonuses={Elf:{DEX:2,INT:1},Dwarf:{CON:2,WIS:1},Halfling:{CHA:2,DEX:1},Orc:{STR:2,CON:1},Tiefling:{CHA:2,INT:1}};if(bonuses[s.ancestry])Object.entries(bonuses[s.ancestry]).forEach(([k,v])=>s.stats[k]+=v);else{s.stats.WIS++;s.stats.CHA++}s.log=[];pushLog('arrival',`${s.name}, a ${s.ancestry.toLowerCase()} ${s.background.toLowerCase()}, arrived in Brackenmere.`);el('#modalRoot').innerHTML='';render();toast('Your chronicle begins.')};};
52: function renderSceneArt(){return `<div class="scene-art"><div class="moon"></div><div class="ridge back"></div><div class="ridge"></div><div class="pine p1"></div><div class="pine p2"></div><div class="pine p3"></div><div class="town"><div class="house small"></div><div class="house"></div><div class="house small"></div></div><div class="fog"></div></div>`}
53: function renderChronicle(){let sc=scenes[s.location%scenes.length];let choices=sc.choices.map(([title,desc,icon,tag],i)=>`<button class="choice" data-choice="${i}"><span class="choice-top"><span class="choice-title">${esc(title)}</span><span class="choice-glyph">${icon}</span></span><span class="choice-desc">${esc(desc)}</span></button>`).join('');el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location"><b>✧ ${esc(sc.region)}</b></div><span class="day">${dayName(s.day)}</span></div><section class="scene">${renderSceneArt()}<div class="scene-tag">${esc(sc.tag)}</div><div class="scene-caption"><h1>${esc(sc.name)}</h1><p>${esc(sc.region.split(' · ')[0])} — The Greenmarch</p></div></section><section class="panel narrative"><p>${esc(s.lastNarration||sc.intro)}<br><span class="italic">${s.turn===0?'The world waits to see what you make of this moment.':'Your story is yours to write. What will you do next?'}</span></p></section><div class="section-heading"><h2>What do you do?</h2><span class="quiet">Choose a path, or write your own</span></div><div class="choices" id="choices">${choices}</div><form class="freeform" id="freeform"><input id="freeText" maxlength="180" autocomplete="off" placeholder="Try anything… talk, explore, make, pray"><button class="send">Act →</button></form><div class="roll-banner ${s.rollText?'show':''}" id="rollBanner"><span class="die">⚄</span><span id="rollText">${esc(s.rollText||'')}</span></div><div class="panel view-panel" style="margin-top:14px"><div class="right-heading"><h3>Recent moments</h3><span class="quiet">Your chronicle</span></div>${s.log.length?s.log.slice(0,3).map(x=>`<div class="feed-entry"><small>${esc(x.kind)} · day ${x.day}</small>${esc(x.text)}</div>`).join(''):'<div class="quiet">The page is still blank.</div>'}</div>`;
54: el('#choices').onclick=e=>{let b=e.target.closest('[data-choice]');if(b)act(sc.choices[+b.dataset.choice][0],sc.choices[+b.dataset.choice][3])};el('#freeform').onsubmit=e=>{e.preventDefault();let text=el('#freeText').value.trim();if(text){actFree(text);el('#freeText').value=''}};}
55: function act(title,tag){let skillsBy={social:'Persuasion',explore:'Survival',faith:'Insight',craft:'Craft',lore:'Arcana',combat:'Athletics'};let skill=skillsBy[tag]||'Insight';let die=1+Math.floor(Math.random()*20),bonus=skillBonus(skill),dc=11,total=die+bonus,success=total>=dc;s.turn++;s.choiceCount++;s.day+=Math.random()<.25?1:0;s.deeds[tag]=(s.deeds[tag]||0)+1;let current=scenes[s.location%scenes.length];let outcomes={social:success?'Your honesty opens a door. Mara, the ferrymaster, shares what she knows—and asks you to keep it quiet.':'The answer comes guarded, but you catch a name: someone has been seen near the bell tower.',explore:success?'You follow the clue beyond the familiar paths. A curious little relic waits where the mist parts.':'The wild keeps its secret for now. Still, you notice a trail leading toward the Lanternwood.',faith:success?'The candle-flame steadies. For one breath, the shrine feels less like a ruin and more like a promise.':'The flame gutters, then burns on. Even unanswered prayers leave a mark.',craft:success?'A little care makes a real difference. The villagers notice—and someone presses a few coins into your hand.':'Your effort is appreciated, though the repair will take more work. A useful lesson, at least.',lore:success?'The old marks resolve into a name: Nym, the Unmoored Star. A fragment of amberglass warms in your palm.':'The marks resist easy reading. You copy them down; knowledge can wait.',combat:success?'You meet the danger with calm and clear purpose. The way ahead opens.':'You keep your footing and avoid the worst of it. The road is still yours.'};let text=outcomes[tag]||'The moment unfolds in a way only you could have set in motion.';if(success&&tag==='explore'&&!s.inventory.some(i=>i.id==='wildflower'))s.inventory.push({id:'wildflower',name:'Moonlit wildflower',icon:'✿',desc:'A pale bloom that only opens after dusk.',type:'herb',value:5,qty:1});if(success&&tag==='craft'){s.gold+=3;text+=' (+3 silver marks)'}if(tag==='