.dataset.action==='use'){if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);gainXP(5);toast('A little restored strength.')}else{i.equipped=!i.equipped;toast(i.equipped?`${i.name} equipped.`:`${i.name} put away.`)}render();return}let sell=e.target.closest('[data-sell]');if(sell){let i=s.inventory.find(x=>x.id===sell.dataset.sell);if(i){s.gold+=Math.max(1,Math.floor(i.value*.7));if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);toast(`Sold ${i.name}.`;
