Math.min(3,s.quests[0].progress+1);if((tag==='lore'||tag==='explore')&&s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1);if(s.quests[0]&&s.quests[0].progress>=s.quests[0].total&&!s.quests[0].done){s.quests[0].done=true;s.gold+=s.quests[0].reward;text+=` Quest complete: “${s.quests[0].name}.” (+${s.quests[0].reward} silver marks)`;gainXP(40)}if(equipment&&['combat','explore','craft'].includes(tag)){equipment.durability=Math.max(0,equipment.durability-1);if(equipment.durability===0){equipment.equipped=false;text+=` Your ${equipment.name} breaks under the strain.`}}gainXP(success?25:12);if(s.turn%3===0){s.location=(s.location+1)%scenes.length;s.day++}s.lastNarration=text;pushLog(tag,text);s.rollText=`${skill} check: d20 ${die} ${bonus+equipBonus>=0?'+':''}
