${Object.entries(s.statBuy).map(([k,v])=>`<div class="option" style="display:flex;align-items:center;justify-content:space-between;gap:12px"><b>${k}</b><button type="button" class="action-btn" data-stat="${k}" data-delta="-1" ${v<=8?'disabled':''}>−</button><b>${v}</b><small>Cost ${statCost(v)}</small><button type="button" class="action-btn" data-stat="${k}" data-delta="1" ${v>=15||spentStats()+statCost(v+1)-statCost(v)>STAT_BUDGET?'disabled':''}>+</button></div>`).join('')}</div><p class="tiny-row"><span>Points spent</span><b>${spentStats()} / ${STAT_BUDGET} · ${STAT_BUDGET-spentStats()} remaining</b></p><div class="modal-actions"><span>All paths begin at level 1. No class is chosen.</span><button class="primary" id="createChar" ${spentStats()>STAT_BUDGET?'disabled':''}>Enter the Greenmarch →</button></div></div></div>`;
el('#ancestryOptions').onclick=e=>{let b=e.target.closest('[data-ancestry]');if(b){s.ancestry=b.dataset.ancestry;openCreator()}};el('#modalRoot').onclick=e=>{let b=e.target.closest('[data-human-stat]');if(b){let k=b.dataset.humanStat;if(s.humanBonus.includes(k)){s.humanBonus=s.humanBonus.filter(x=>x!==k)}else if(s.humanBonus.length<2)s.humanBonus.push(k);else toast('Choose exactly two abilities.');openCreator();return}b=e.target.closest('[data-stat]');if(b){let k=b.dataset.stat,v=+s.statBuy[k]+ +b.dataset.delta,next={...s.statBuy,[k]:v};if(v>=8&&v<=15&&spentStats(next)<=STAT_BUDGET){s.statBuy=next;openCreator()}return}b=e.target.closest('[data-bg]');if(b){s.background=b.dataset.bg;openCreator();return}b=e.target.closest('[data-skill]');if(b){let a=s.skills.slice();if(a.includes(b.dataset.skill))a=a.filter(x=>x!==b.dataset.skill);else if(a.length<2)a.push(b.dataset.skill);else{toast('Choose exactly two practiced skills.');return}s.skills=a;openCreator();return}if(e.target.closest('#createChar')){let name=el('#charName').value.trim();if(!name){toast('Give your wayfarer a name first.');return}if(s.skills.length!==2||s.humanBonus?.length!==2&&s.ancestry==='Human'||spentStats()>STAT_BUDGET){toast('Complete the choices within the 27-point budget.');return}s.name=name;s.created=true;s.location=0;s.stats={...s.statBuy};Object.entries(ancestryBonuses()).forEach(([k,v])=>s.stats[k]+=v);s.log=[];pushLog('arrival',`${s.name}, a ${s.ancestry.toLowerCase()} ${s.background.toLowerCase()}, arrived in Brackenmere.`);el('#modalRoot').innerHTML='';render();toast('Your chronicle begins.')}}}
window.openCreator=openCreator;
function encounterNpc(){return ({0:'Mara',1:'Iven',2:'Orin',3:'Rowan',4:'Orin'})[s.location%scenes.length]}
function npcById(id){return npcs.find(n=>n.id===id)}
function currentShop(){return ({0:'grocer',1:'general',2:'smith',3:'apothecary',4:'apothecary'})[s.location%scenes.length]}
function getStock(shop){if(!s.shopStock[shop.id])s.shopStock[shop.id]=makeShopStock(shop).map(i=>({...i,qty:1}));return s.shopStock[shop.id]}
function encounterNarrative(tag,success,title){let id=encounterNpc(),npc=npcById(id),r=s.relations[id]||0;if(tag==='social'){let delta=success?1:0;s.relations[id]=Math.min(5,r+delta);if(success)return `${npc.name} responds to your ${title.toLowerCase()} with a more open expression. ${npc.temper}; the exchange gives you a clearer sense of what matters to them: ${npc.likes}.`;return `${npc.name} considers your ${title.toLowerCase()} carefully, then keeps their counsel. Their ${npc.temper.toLowerCase()} nature leaves little room for easy trust.`}let scene=scenes[s.location%scenes.length];let lines={explore:success?`Your effort carries you further into ${scene.name}. You uncover a small find and a trace that links this place to the bell’s mystery.`:`The place yields no easy answer. ${scene.name} leaves you with a detail worth remembering, but no certainty.`,faith:success?`A quiet moment settles over ${scene.name}. The old rite answers with a warmth rather than words.`:`The rite passes without a sign. The silence feels less empty than it did before.`,craft:success?`Your work holds. Someone nearby notices the care you took and leaves a few silver marks in thanks.`:`The repair is serviceable, though the materials resist your hands. You learn what the task will require.`,lore:success?`The fragments resolve into an old name tied to the bell. The discovery sharpens the mystery rather than settling it.`:`The writing is worn and incomplete. You preserve what you can read for another look.`,combat:success?`You face the danger on your terms and come away with a clearer route through ${scene.name}.`:`You avoid the worst of the danger, though the encounter leaves a mark on your equipment.`};return lines[tag]||`Your choice changes the shape of the moment in ${scene.name}.`}
function renderChronicle(){let sc=scenes[s.location%scenes.length],npc=npcById(encounterNpc()),shop=shops.find(x=>x.id===currentShop()),stock=shop?getStock(shop):[],relation=s.relations[npc.id]||0,choices=sc.choices.map(([title,desc,icon,tag],i)=>`<button class="choice" data-choice="${i}"><span class="choice-top"><span class="choice-title">${esc(title)}</span><span class="choice-glyph">${icon}</span></span><span class="choice-desc">${esc(desc)}</span></button>`).join('');el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location"><b>✧ ${esc(sc.region)}</b></div><span class="day">${dayName(s.day)}</span></div><section class="scene">${renderSceneArt()}<div class="scene-tag">${esc(sc.tag)}</div><div class="scene-caption"><h1>${esc(sc.name)}</h1><p>${esc(sc.region.split(' · ')[0])} — The Greenmarch</p></div></section><section class="panel narrative"><p>${esc(s.lastNarration||sc.intro)}<br><span class="italic">${s.turn===0?'The first moment is yours.':'Each choice leaves its own trace.'}</span></p></section><section class="panel view-panel"><div class="right-heading"><div><div class="eyebrow">Someone here</div><h3>${esc(npc.name)} · ${esc(npc.role)}</h3></div><span class="heart">${'♥'.repeat(Math.max(1,relation+1))}</span></div><p>${esc(npc.temper)}. Values ${npc.likes}. Relationship: ${relation>=3?'trusted':relation>=1?'warming':'new acquaintance'}${s.joined.includes(npc.id)?' · traveling with you':''}.</p><div class="chips"><button class="action-btn" data-npc-action="talk">Speak with ${esc(npc.name.split(' ')[0])}</button>${npc.willing&&!s.joined.includes(npc.id)?`<button class="action-btn" data-npc-action="recruit" ${relation<3?'disabled':''}>Invite to travel ${relation<3?'(trust 3+)':''}</button>`:''}</div></section><div class="section-heading"><h2>What do you do?</h2><span class="quiet">Choose a path, or write your own</span></div><div class="choices" id="choices">${choices}</div><form class="freeform" id="freeform"><input id="freeText" maxlength="180" autocomplete="off" placeholder="Try anything… talk, explore, make, pray"><button class="send">Act →</button></form><div class="roll-banner ${s.rollText?'show':''}" id="rollBanner"><span class="die">⚄</span><span id="rollText">${esc(s.rollText||'')}</span></div>${shop?`<section class="panel view-panel"><div class="right-heading"><div><div class="eyebrow">In-world merchant · ${esc(shop.kind)}</div><h2 style="margin-top:5px">${shop.icon} ${esc(shop.name)}</h2></div><span class="quiet">Keeper: ${esc(shop.keeper)}</span></div><p>Only available while you are here. Stock is limited; prices reflect each item’s rarity.</p>${stock.map(i=>`<div class="list-row"><div class="item-icon">${i.icon}</div><div class="list-copy"><div class="list-title">${esc(i.name)} <span class="chip">${esc(i.rarity)}</span></div><div class="list-desc">${itemDetails(i)} · ◈${i.price}</div></div><button class="action-btn" data-purchase="${esc(i.id)}" ${i.qty<1||s.gold<i.price?'disabled':''}>Buy</button></div>`).join('')||'<div class="quiet">This merchant is sold out for now.</div>'}</section>`:''}<div class="panel view-panel" style="margin-top:14px"><div class="right-heading"><h3>Recent moments</h3><span class="quiet">Your chronicle</span></div>${s.log.length?s.log.slice(0,3).map(x=>`<div class="feed-entry"><small>${esc(x.kind)} · day ${x.day}</small>${esc(x.text)}</div>`).join(''):'<div class="quiet">The page is still blank.</div>'}</div>`;el('#choices').onclick=e=>{let b=e.target.closest('[data-choice]');if(b)act(sc.choices[+b.dataset.choice][0],sc.choices[+b.dataset.choice][3])};el('#freeform').onsubmit=e=>{e.preventDefault();let x=el('#freeText').value.trim();if(x){actFree(x);el('#freeText').value=''}};el('#mainContent').onclick=e=>{let b=e.target.closest('[data-npc-action]');if(b){if(b.dataset.npcAction==='talk'){act(`Speak with ${npc.name}`, 'social')}else if(relation>=3){s.joined.push(npc.id);pushLog('companion',`${npc.name} agreed to travel with you.`);s.lastNarration=`After the trust you have built, ${npc.name} chooses to join your travels. Their distinct perspective will accompany the road ahead.`;gainXP(20);render();toast(`${npc.name} joined you.`)}return}b=e.target.closest('[data-purchase]');if(b){let item=stock.find(x=>x.id===b.dataset.purchase);if(!item||item.qty<1)return;if(s.gold<item.price){toast('Not enough silver marks.');return}s.gold-=item.price;item.qty--;let owned=s.inventory.find(x=>x.id===item.id);if(owned)owned.qty++;else s.inventory.push({...item,qty:1,equipped:false});pushLog('trade',`You bought ${item.name} from ${shop.name}.`);toast(`${item.name} added to your pack.`);render()}}}
function act(title,tag){let skillsBy={social:'Persuasion',explore:'Survival',faith:'Insight',craft:'Craft',lore:'Arcana',combat:'Athletics'};let skill=skillsBy[tag]||'Insight',die=1+Math.floor(Math.random()*20),bonus=skillBonus(skill),equipment=s.inventory.find(i=>i.equipped&&canUse(i)),equipBonus=equipment?1:0,dc=11,total=die+bonus+equipBonus,success=total>=dc;s.turn++;s.choiceCount++;if(Math.random()<.25)s.day++;s.deeds[tag]=(s.deeds[tag]||0)+1;let text=encounterNarrative(tag,success,title);if(success&&tag==='explore'){let found=makeItem(Math.random()<.5?'herb':'charm','find');s.inventory.push(found);text+=` ${found.name} turns up among the old stones.`}if(success&&tag==='craft'){s.gold+=3;text+=' (+3 silver marks)'}if(tag==='social'&&s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1);if((tag==='lore'||tag==='explore')&&s.quests[0]&&!s.quests[0].done)s.quests[0].progress=Math.min(3,s.quests[0].progress+1);if(s.quests[0]&&s.quests[0].progress>=s.quests[0].total&&!s.quests[0].done){s.quests[0].done=true;s.gold+=s.quests[0].reward;text+=` Quest complete: “${s.quests[0].name}.” (+${s.quests[0].reward} silver marks)`;gainXP(40)}if(equipment&&['combat','explore','craft'].includes(tag)){equipment.durability=Math.max(0,equipment.durability-1);if(equipment.durability===0){equipment.equipped=false;text+=` Your ${equipment.name} breaks under the strain.`}}gainXP(success?25:12);if(s.turn%3===0){s.location=(s.location+1)%scenes.length;s.day++}s.lastNarration=text;pushLog(tag,text);s.rollText=`${skill} check: d20 ${die} ${bonus+equipBonus>=0?'+':''}${bonus+equipBonus} = ${total} vs DC ${dc} · ${success?'Success':'Complication'}.`;earned();render()}
function actFree(text){let lower=text.toLowerCase();if(/(join|recruit|travel with|come with me|follow me)/.test(lower)){let npc=npcById(encounterNpc()),r=s.relations[npc.id]||0;if(npc.willing&&r>=3&&!s.joined.includes(npc.id)){s.joined.push(npc.id);s.lastNarration=`${npc.name} weighs your invitation, then agrees to join your travels. Their ${npc.temper.toLowerCase()} nature will shape the road ahead.`;gainXP(20);pushLog('companion',`${npc.name} joined you.`);render();return}toast(`${npc.name} is not ready to travel with you.`)}let tag=/pray|shrine|god|offering|worship/.test(lower)?'faith':/craft|make|repair|build|cook|gather|forage|brew/.test(lower)?'craft':/talk|ask|persuad|convince|greet|tell|listen|friend|flirt|speak/.test(lower)?'social':/read|rune|study|research|remember|history/.test(lower)?'lore':/fight|attack|strike|defend|duel|hunt/.test(lower)?'combat':'explore';act(text,tag);s.lastNarration=`Your choice to ${text.charAt(0).toLowerCase()+text.slice(1)} shapes what follows. ${s.lastNarration}`;save();render()}
function renderInventory(){let shop=shops.find(x=>x.id===currentShop());el('#mainContent').innerHTML=`<div class="welcome-line"><div class="location">THE WAYFARER · WHAT YOU CARRY</div><span class="day">◈ ${s.gold} silver marks</span></div><section class="panel view-panel"><div class="eyebrow">Pack & provisions</div><h2 style="margin-top:6px">Inventory</h2><p>Equipment carries weight, wears with use, and may demand a minimum ability. Consumables restore a little resolve. ${shop?`Sell unwanted goods to ${esc(shop.keeper)} while you are here.`:'Trading is only possible when you meet a merchant in the world.'}</p>${s.inventory.length?s.inventory.map(i=>{let usable=canUse(i),consumable=['food','drink','potion','remedy','herb'].includes(i.type);return `<div class="list-row"><div class="item-icon">${i.icon}</div><div class="list-copy"><div class="list-title">${esc(i.name)} ${i.equipped?'<span class="chip">Equipped</span>':''}</div><div class="list-desc">${itemDetails(i)} · x${i.qty}</div></div><button class="action-btn" data-item="${esc(i.id)}" ${!usable?'disabled':''}>${consumable?'Use':i.equipped?'Unequip':'Equip'}</button><button class="action-btn" data-sell="${esc(i.id)}" ${!shop?'disabled title="Find a merchant in the world to sell items."':''}>Sell · ◈${Math.max(1,Math.floor(i.value*.7))}</button></div>`}).join(''):'<div class="quiet">Your pack is empty.</div>'}</section><section class="panel view-panel"><div class="eyebrow">Traveling companions</div><h2 style="margin-top:6px">People beside you</h2>${s.joined.length?s.joined.map(id=>{let n=npcById(id);return `<div class="list-row"><div class="item-icon">${n.icon}</div><div class="list-copy"><div class="list-title">${n.name} · ${n.role}</div><div class="list-desc">${n.temper}. Values ${n.likes}.</div></div><span class="chip">Traveling</span></div>`}).join(''):'<div class="quiet">No one has joined your travels yet.</div>'}</section>`;el('#mainContent').onclick=e=>{let b=e.target.closest('[data-item]');if(b){let i=s.inventory.find(x=>x.id===b.dataset.item);if(!i)return;if(['food','drink','potion','remedy','herb'].includes(i.type)){if(!canUse(i)){toast('This item is broken or your abilities do not meet its requirement.');return}if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);gainXP(5);pushLog('use',`You used ${i.name}.`);toast('The item’s effect settles in.')}else if(i.equipped){i.equipped=false}else if(canUse(i)){i.equipped=true;toast(`${i.name} equipped.`)}render();return}let sell=e.target.closest('[data-sell]');if(sell){let i=s.inventory.find(x=>x.id===sell.dataset.sell);if(i){s.gold+=Math.max(1,Math.floor(i.value*.7));if(i.qty>1)i.qty--;else s.inventory=s.inventory.filter(x=>x!==i);toast(`Sold ${i.name}.`);render()}return}}}
function renderRight(){let open=s.quests.filter(q=>!q.done);el('#rightbar').innerHTML=`<section class="panel right-card"><div class="right-heading"><h3>In your thoughts</h3><button class="link-btn" data-tab="quests">All quests →</button></div>${open.length?open.slice(0,2).map(q=>`<div class="quest"><div class="quest-name">${esc(q.name)}</div><div class="quest-sub">${esc(q.desc)}</div><div class="meter"><span style="width:${q.progress/q.total*100}%"></span></div></div>`).join(''):'<div class="quiet">No open quests. Follow your curiosity.</div>'}</section><section class="panel right-card"><div class="right-heading"><h3>Familiar faces</h3><span class="quiet">Persistent ties</span></div>${npcs.map(n=>{let r=s.relations[n.id]||0;return `<div class="npc-row"><div class="avatar">${n.icon}</div><div class="npc-copy"><div class="npc-name">${n.name}</div><div class="npc-note">${n.role} · ${s.joined.includes(n.id)?'Traveling':r>=3?'Trusted':r?'Warming':'Acquaintance'}</div></div><span class="heart">${'♥'.repeat(Math.max(1,r+1))}</span></div>`}).join('')}</section><section class="panel right-card"><div class="right-heading"><h3>Your bearings</h3><button class="link-btn" data-tab="character">Details →</button></div><div class="stat-grid">${Object.entries(s.stats).map(([k,v])=>`<div class="stat"><div class="stat-label">${k}</div><div class="stat-value">${v} <small>${modText(mod(v))}</small></div></div>`).join('')}</div><div class="tiny-row" style="margin-top:12px"><span>Silver marks</span><b style="color:var(--gold2)">◈ ${s.gold}</b></div><div class="tiny-row"><span>Pack weight</span><b>${s.inventory.reduce((n,i)=>n+i.weight*i.qty,0).toFixed(1)} lb</b></div></section><section class="panel right-card"><div class="eyebrow">A whisper at the edge</div><p style="font:13px/1.5 var(--serif);color:#c5cabb;margin:8px 0 0">“The bell remembers a name the living have forgotten.”</p></section>`;el('#rightbar').onclick=e=>{let b=e.target.closest('[data-tab]');if(b){s.tab=b.dataset.tab;render()}}}
function init(){document.body.addEventListener('click',e=>{let b=e.target.closest('[data-tab]');if(b){s.tab=b.dataset.tab;render()}});el('#resetBtn').onclick=()=>{if(confirm('Begin a new chronicle? Your current story will be erased.')){s=initial();save();render()}};render()}
